            "db": str(DB.relative_to(ROOT)) if DB.is_relative_to(ROOT) else str(DB),
            "sha256": hashlib.sha256(dbbytes).hexdigest()[:12],
            "bytes": len(dbbytes),
            "user_version": cur.execute("PRAGMA user_version").fetchone()[0],
            "asof": asof,
            "tables": len(tables),
