    js=set(json.loads(gr))
    tbl={r[0] for r in con.execute("select ref_id from specification_source_links where specification_id=?", (sid,))}
    print(f'  spec {sid}: JSON {len(js)} refs | junction {len(tbl)} rows | identical: {js==tbl}')
print('\n=== are the JSON-held ref_ids real, and would anything catch it if not? ===')
live={r[0] for r in con.execute("select ref_id from evidence_sources")}
bad=0; tot=0
for t,c in [('specifications','governing_refs'),('convergence_assessment','clinical_sources'),
