import re, pathlib, sqlite3
con=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
sql={t:(s or '') for t,s in con.execute("select name,sql from sqlite_master where type='table'")}
def has_check(t,c):
    for m in re.finditer(r'CHECK\s*\((?:[^()]|\([^()]*\))*\)', sql.get(t,''), re.I):
        if re.search(r'\b'+re.escape(c)+r'\b', m.group(0)): return True
    return False
# Declared vocabularies in the Pydantic layer: Literal[...] and Enum classes.
print('=== fields the schemas DECLARE a vocabulary for ===')
for p in sorted(pathlib.Path('schemas').glob('*.py')):
    txt=p.read_text()
    for m in re.finditer(r'^\s{4}(\w+)\s*:\s*(?:Optional\[)?Literal\[([^\]]+)\]', txt, re.M):
        field, vals = m.group(1), [v.strip().strip('\'"') for v in m.group(2).split(',')]
        print(f'{p.name}:{field} = {vals}')
PY

