import sqlite3, json
r=sqlite3.connect('file://$SCRATCH/r2.db?mode=ro',uri=True)
print('user_version:', r.execute('PRAGMA user_version').fetchone()[0])
print('convergence_sources rows:', r.execute('select count(*) from convergence_sources').fetchone()[0])
for role,n in r.execute('select role,count(*) from convergence_sources group by 1 order by 2 desc'): print(f'   {n:3d}  {role}')
# parity against the JSON it was built from
tot=0
for row in r.execute("select convergence_id,clinical_sources,co1_sources,co2_sources,down_weighted_sources,discounted_sources from convergence_assessment"):
    cid=row[0]
    for col,role in zip(row[1:], ['clinical','co1','co2','down_weighted','discounted']):
        js=set(json.loads(col)) if col else set()
        tb={x[0] for x in r.execute("select ref_id from convergence_sources where convergence_id=? and role=?", (cid,role))}
        tot+=len(js)
        assert js==tb, (cid, role, js, tb)
print(f'backfill matches the JSON exactly for all roles: {tot} pointers')
print('\nFK now protects them:')
w=sqlite3.connect('$SCRATCH/r2.db'); w.execute('PRAGMA foreign_keys=ON')
